{
  "part": {
    "name": "Ergonomic mouse-like housing with control wheel",
    "description": "A streamlined, approximately 102.5 mm long by 65.5 mm wide by 31.9 mm high solid housing with a convex upper deck, sculpted lateral flanks, low front nose, rounded rear heel, lower base surface, rectangular control-wheel recess, and a separate vertically oriented wheel. The STEP model contains two solids: the main housing and the control wheel.",
    "source_views": [
      "front",
      "back",
      "left",
      "right",
      "top",
      "bottom",
      "toprightiso"
    ],
    "symmetry_note": "The main housing is approximately bilaterally symmetric about its longitudinal center plane near x=26.9 mm. Small left-right differences and a slight angular offset of the central recess and wheel are present; exact symmetry is not indicated by the B-rep."
  },
  "Section": [
    {
      "id": "S01",
      "name": "Upper ergonomic deck",
      "features included": [
        "broad palm-support surface",
        "central wheel opening",
        "convex structural shell",
        "transitions to both lateral flanks"
      ],
      "function intent": "Provides the principal user-contact surface and supports the hand while positioning the wheel opening near the longitudinal centerline.",
      "physical behavior": "Its doubly curved shape spreads hand pressure over a broad area and transfers downward loads into the side flanks, nose, rear heel, and lower body. The opening interrupts the deck locally to provide access to the wheel recess.",
      "geometry": "One large freeform B-spline patch with a convex ergonomic crown and an internal opening around the control recess.",
      "location": "Upper side of the main housing, extending longitudinally between the front nose and rear heel and laterally between the two side flanks.",
      "colour": {
        "R": 181,
        "G": 214,
        "B": 224
      },
      "major_faces": [
        {
          "face_code": "0000",
          "name": "Convex upper deck",
          "Brep_id": "FACE 6",
          "description": "Large upper B-spline surface with two wires, including the boundary of the central control opening."
        }
      ],
