    {
      "id": "S03",
      "name": "Rear palm heel",
      "features included": [
        "rounded rear termination",
        "palm-load transition",
        "upper-to-base closure"
      ],
      "function intent": "Closes the elevated rear portion of the housing and supports the transition beneath the user's palm.",
      "physical behavior": "Its broad curvature distributes palm and handling loads around the rear perimeter and into the side flanks and underside without abrupt stiffness changes.",
      "geometry": "A broad compound-curved B-spline end patch spanning the rear width and wrapping between the upper and lower surfaces.",
      "location": "Rear longitudinal end of the housing at approximately z=-25 to -5.5 mm.",
      "colour": {
