      "name": "Left lateral flank",
      "features included": [
        "left sidewall",
        "perimeter support rail",
        "ergonomic side contour"
      ],
      "function intent": "Closes and stiffens the left side of the housing while providing a smooth gripping and perimeter-support surface.",
      "physical behavior": "Acts as a deep curved sidewall that carries deck loads toward the underside and resists lateral squeezing and bending of the housing.",
      "geometry": "One elongated freeform B-spline patch with outward convexity and rounded transitions at both longitudinal ends.",
      "location": "Negative-x side of the main housing.",
      "colour": {
        "R": 76,
        "G": 83,
        "B": 145
      },
      "major_faces": [
        {
