    {
      "id": "S06",
      "name": "Lower base surface",
      "features included": [
        "bottom closure",
        "support footprint",
        "lower longitudinal spine"
      ],
      "function intent": "Closes the bottom of the housing and provides the primary downward-facing support region.",
      "physical behavior": "Spans between the lateral flanks, carries compressive loads to an external support surface, and stabilizes the housing against rocking and torsional deformation.",
      "geometry": "A broad, relatively shallow B-spline underside patch with a near-horizontal central region and blended perimeter curvature.",
      "location": "Lowest side of the main housing, near y=2.2 to 3.3 mm through much of its area.",
      "colour": {
