    {
      "id": "S07",
      "name": "Control-wheel recess",
      "features included": [
        "rectangular wheel pocket",
        "two opposed lateral locating walls",
        "front and rear pocket walls",
        "recess floor",
        "wheel clearance opening"
      ],
      "function intent": "Provides clearance and positional control for the separate wheel while locally interrupting the upper deck.",
      "physical behavior": "The four planar walls define the allowable wheel envelope and resist lateral or longitudinal displacement. The floor closes the recess and can react downward assembly or operating loads. The open top allows the wheel to protrude for user access.",
      "geometry": "A slightly tilted rectangular pocket formed by four planar sidewalls and one planar floor; the pocket is open through the upper deck.",
      "location": "Near the longitudinal centerline of the upper housing, around x=25 to 30.6 mm and z=43.5 to 59.3 mm.",
      "colour": {
        "R": 207,
        "G": 179,
        "B": 122
      },
      "major_faces": [
        {
          "face_code": "0006",
          "name": "Pocket left wall",
          "Brep_id": "FACE 0",
          "description": "Negative-x planar wall of the rectangular wheel recess, with a slight longitudinal tilt."
        },
        {
          "face_code": "0007",
          "name": "Pocket rear wall",
          "Brep_id": "FACE 1",
          "description": "Planar transverse wall at the lower-z end of the wheel recess."
        },
        {
          "face_code": "0008",
          "name": "Pocket right wall",
          "Brep_id": "FACE 2",
          "description": "Positive-x planar wall opposite FACE 0 and approximately parallel to it."
        },
        {
          "face_code": "0009",
          "name": "Pocket front wall",
          "Brep_id": "FACE 3",
          "description": "Planar transverse wall at the higher-z end of the wheel recess."
        },
        {
          "face_code": "0010",
          "name": "Pocket floor",
          "Brep_id": "FACE 4",
          "description": "Horizontal planar bottom of the recess at y=10 mm, adjacent to all four pocket walls."
        }
      ],
