    {
      "id": "S08",
      "name": "Control wheel",
      "features included": [
        "user-operated rotary interface",
        "rounded tread",
        "two planar side faces",
        "separate moving solid"
      ],
      "function intent": "Provides a finger-operated control interface, nominally intended to rotate about a transverse axis while remaining captured within the central recess.",
      "physical behavior": "The rounded toroidal tread provides a smooth contact surface for tangential finger force. The two flat side faces define the wheel width and can provide axial clearance or bearing-interface regions. The surrounding recess limits translation while allowing intended rotation if suitable pivots are added.",
      "geometry": "A narrow wheel-like solid composed of two joined toroidal surface patches and two opposed planar circular or near-circular side faces.",
      "location": "Centered within and projecting above the control-wheel recess, around x=25.4 to 30.4 mm, y=15.1 to 29.1 mm, and z=44.2 to 58.3 mm.",
      "colour": {
        "R": 57,
        "G": 132,
        "B": 67
      },
      "major_faces": [
        {
          "face_code": "0011",
          "name": "Wheel left side face",
          "Brep_id": "FACE 12",
          "description": "Planar negative-x side face of the wheel, bounded by a single closed edge."
        },
        {
          "face_code": "0012",
          "name": "Wheel left tread",
          "Brep_id": "FACE 11",
          "description": "Toroidal tread patch extending from the left side face toward the wheel crown."
        },
        {
          "face_code": "0013",
          "name": "Wheel right tread",
          "Brep_id": "FACE 13",
          "description": "Second toroidal tread patch continuing across the crown toward the right side face."
        },
        {
          "face_code": "0014",
          "name": "Wheel right side face",
          "Brep_id": "FACE 14",
